          "prompt": "Выберите верные суждения о науке и запишите цифры, под которыми они указаны.\n1) Наука – особая форма деятельности человека, обеспечивающая получение и систематизацию нового знания. \n2) Прогностическая функция науки позволяет предвидеть последствия происходящих изменений. \n3) Наука и образование в современном обществе существуют обособлено друг от друга. \n4) Наука влияет на формирование картины мира в мировоззрении человека. \n5) Виды науки можно различать по среде, материалу, в котором реализуются художественные образы.",
