          "id": "test-08-q-022",
          "number": 22,
          "type": "text",
          "prompt": "Представьте, что вы помогаете учителю сделать презентацию к уроку «Тенденции в образовании». Один из слайдов называется: «Демократизация образования». Что бы вы включили в этот слайд? Запишите цифры, под которыми указаны эти черты.\n1) Применение здоровьесберегающих технологий\n2) Открытие большого количество школ для детей, проживающих в сельской местности\n3) Открытие вечерних школ для взрослых людей, которые по каким-то причинам не смогли завершить образование \n4) Возможность сдавать экзамены из дома с помощью системы прокторинга\n5) Уважительное отношение к ученику \n6) Открытие школ для не русскоговорящих детей мигрантов",
