          "number": 35,
          "type": "text",
          "prompt": "Учащиеся на уроке изучали социальные нормы. Какие из перечисленных признаков характеризуют мораль? Запишите цифры, под которыми указаны признаки морали.\n1) Закреплённость в нормативно-правовых актах\n2) Государственная поддержка\n3) Наступление юридической ответственности за несоблюдение\n4) За несоблюдение можно подвергнуться общественному порицанию\n5) Не закрепляется в каких-либо документах\n6) Основывается на представлениях людей о добре и зле",
