          "prompt": "Выберите верные суждения о социальных группах и их видах и запишите цифры, под которыми они указаны.\n1) Демографические группы выделяют по этносоциальному составу.\n2) В формальной группе межличностные взаимодействия, как правило, основаны на взаимной симпатии, общем интересе или привычке.\n3) Принадлежность к различным социальным группам определяет положение человека в обществе.\n4) Социальные группы – устойчивые совокупности людей, которые имеют отличные, только им присущие признаки (социальное положение, интересы, ценностные ориентации).\n5) Группы и организации оказывают влияние на поведение человека.",
