          "number": 2,
          "type": "text",
          "prompt": "Выберите верные суждения о межнациональных отношениях и запишите цифры, под которыми они указаны.\n1) Любые межнациональные отношения законодательно регламентированы.\n2) Одним из способов предотвращения межнациональных конфликтов в демократическом обществе является соблюдение прав и свобод каждой народности и нации.\n3) Этносоциальный конфликт характеризуется состоянием взаимных претензий, противостоянием племён, народов и наций друг другу.\n4) Одной из причин этносоциальных конфликтов является существующее между этносами неравенство в уровне жизни, различное представительство в престижных профессиях, социальных слоях, органах власти.\n5) Толерантность представляет собой конфликт между представителями разных наций и народностей.",
