          "prompt": "Выберите верные суждения о социальной структуре общества и запишите цифры, под которыми они указаны.\n1) Социальные группы различны по характеру, масштабу, роли, которую они играют в обществе,\n2) Взаимосвязанные социальные группы образуют социальную структуру общества.\n3) Признаком, свидетельствующим о переходе индивида в маргинальное состояние, является разрыв экономических, социальных и культурных связей с прежней социальной общностью и попытки установить их с новой.\n4) Человек в современном обществе принадлежит, как правило, к одной социальной группе.\n5) Только с политической деятельностью связывают существование слоёв населения, различающихся по уровню доходов.",
