          "prompt": "Выберите верные суждения об этнических общностях и запишите цифры, под которыми они указаны.\n1) В Российской Федерации каждый имеет право на пользование родным языком, на свободный выбор языка общения, воспитания, обучения и творчества.\n2) Межнациональная интеграция подразумевает сближение народов, укрепление связей между ними, взаимовлияние и взаимообогащение культур разных этносов.\n3) К наиболее древним этническим общностям относятся нации.\n4) Важнейшей предпосылкой формирования этноса является общность территории.\n5) Признаком этнической общности служат общие политические предпочтения.",
