          "prompt": "Выберите верные суждения и запишите цифры, под которыми они указаны.\n1) Социальная стратификация отражает строение общества.\n2) Социальная стратификация выражается в социальном расслоении.\n3) В основу деления общества на страты положены доход, престиж, образование.\n4) Стратификационная структура общества отражает социальное неравенство людей.\n5) К горизонтальному виду мобильности относится получение внеочередного воинского звания.\n6) Социальная мобильность – это разделение общества на группы, занимающие разное положение.",
