          "prompt": "Выберите верные суждения о социальных статусах и социальных ролях. Запишите цифры, под которыми они указаны.\n1) Социальная роль - это образец поведения, который признан для людей в определенном обществе. \n2) Личный статус - это положение человека, которое он занимает в малой группе, в зависимости от оценки его индивидуальных качеств.\n3) Социальный статус не определяет положение индивида или группы в социальной системе.\n4) Социальная роль - это ожидаемое поведение людей в соответствии с имеющимся статусом.\n5) Между социальными ролями может возникать ролевой конфликт.\n6) Приобретенный статус - это положение, которое заранее предписывается индивиду обществом.",
