          "id": "test-11-q-022",
          "number": 22,
          "type": "text",
          "prompt": "Выберите верные суждения о социальной стратификации и социальной мобильности. Запишите цифры, под которыми они указаны.\n1) Проявлением стратификации общества выступает неравенство индивидов относительно тех социальных обязанностей и ролей, которые они выполняют.\n2) Индивидуальная мобильность представляет собой изменение положения человека в социальной структуре общества.\n3) Групповая мобильность, как правило, преобладает в тех обществах, в которых главное значение придаётся прирождённому статусу.\n4) По сравнению с классовой структурой социальная стратификация выделяет меньшее количество слоёв.\n5) Принадлежность к имущественному, властному или профессиональному слою игнорируется при ранжировании людей по степени престижа в обществе.",
