          "prompt": "Выберите верные суждения о социальном конфликте и запишите цифры, под которыми они указаны.\n1) Институциональные конфликты запрещены во всех обществах.\n2) Социальный конфликт — это наивысшая стадия развития противоречий в отношениях между людьми, социальными группами, общества в целом.\n3) Легитимные и противоправные конфликты различают в зависимости от масштабов социальных потрясений.\n4) Социальный конфликт характеризуется столкновением противоположно направленных интересов, целей, позиций субъектов взаимодействия.\n5) Конфликтное взаимодействие может проявляться в таких формах, как спор, ультиматум, демонстрация силы, вооружённое столкновение и т.п.",
