          "number": 4,
          "type": "text",
          "prompt": "Выберите верные суждения о социальных нормах и запишите цифры, под которыми они указаны.\n1) К функциям социальных норм относят интегрирование индивидов в систему общественных отношений.\n2) Социальные нормы позволяют контролировать, регулировать и оценивать поведение людей.\n3) К видам социальных норм относятся социальные санкции.\n4) Видами социальных норм являются обычаи и традиции.\n5) Соблюдение социальных норм всегда достигается мерами государственного принуждения.",
