          "number": 5,
          "type": "text",
          "prompt": "Выберите верные суждения о социальных нормах и запишите цифры, под которыми они указаны.\n1) Социальные нормы – установленные в обществе правила поведения, регулирующие отношения между людьми, общественную жизнь.\n2) Социальные нормы являются одним из элементов социального контроля.\n3) От других видов социальных норм обычаи отличаются тем, что в них всегда выражаются представления людей о хорошем и плохом, о добре и зле.\n4) Любая организация может устанавливать нормы права.\n5) Социальные нормы призваны способствовать интеграции индивида в социум.",
