          "number": 7,
          "type": "text",
          "prompt": "Выберите верные суждения об отклоняющемся поведении и запишите цифры, под которыми они указаны.\n1) Отклоняющееся поведение всегда является негативным.\n2) Опасное отклоняющееся поведение, нарушающее нормы права и причиняющее вред обществу, называют делинквентным.\n3) Поведение, отклоняющееся от социальных норм, называют девиантным.\n4) Отклоняющееся поведение не соответствует социальным ожиданиям.\n5) Девиантное поведение может быть только индивидуальным.",
