          "prompt": "Выберите верные суждения о социальном контроле и запишите цифры, под которыми они указаны.\n1) Социальный контроль — это совокупность средств и методов регулирования поведения человека в обществе, препятствующих отклоняющемуся поведению.\n2) В структуру социального контроля входят социальные нормы и социальные санкции.\n3) Социальный контроль препятствует установлению социальной стабильности.\n4) Социальные санкции — это правила поведения, принятые в обществе.\n5) Социальные санкции могут быть как позитивными, так и негативными.",
          "required": true,
          "points": 1,
          "options": [

          ]
