          "prompt": "Ниже приведён ряд терминов. Все они, за исключением двух, относятся к видам социальных норм.\n1) обычаи и традиции; 2) мораль; 3) санкция; 4) этикет; 5) девиация; 6) закон.\nНайдите два признака, «выпадающие» из общего ряда, и запишите в таблицу цифры, под которыми они указаны.",
