          "prompt": "Выберите верные суждения о семье и её функциях и запишите цифры, под которыми они указаны.\n1) Досуговая функция семьи проявляется в предоставлении определённого социального статуса членам семьи, в выполнении роли социального лифта.\n2) Семья призвана создать условия для физического, психического, эмоционального и интеллектуального развития ребёнка.\n3) Члены семьи связаны общностью быта, взаимной материальной и моральной ответственностью.\n4) Рекреационная функция семьи проявляется в предоставлении определённого социального статуса членам семьи, в выполнении роли социального лифта.\n5) Семья является одним из субъектов социального контроля.",
