          "prompt": "Ниже приведён ряд терминов. Все они, за исключением двух, относятся к понятию «рыночная экономика».\n1) государственный план;\n2) свобода производителя;\n3) предпринимательство;\n4) централизованное ценообразование;\n5) спрос;\n6) равновесная цена.\nНайдите два термина «выпадающих» из общего ряда, и запишите в цифры, под которыми они указаны.",
