          "prompt": "Экономика страны Z основана на крупном машинном производстве; в ней доминирует тяжёлая промышленность. Какие признаки позволяют сделать вывод о том, что в стране Z командная (плановая) экономика? Запишите цифры, под которыми они указаны.\n1) господство государственной собственности на средства производства\n2) зависимость продовольственного рынка от импортных товаров\n3) необходимость решения проблемы ограниченности ресурсов\n4) отсутствие конкуренции производителей\n5) директивное ценообразование\n6) наличие трудового законодательства",
