          "prompt": "В государстве Z большинство предприятий находятся в частной собственности, но действуют государственные и муниципальные предприятия. Какие из перечисленных признаков позволяют сделать вывод о том, что в стране Z рыночная экономика? Запишите цифры, под которыми они указаны.\n1) Каждый гражданин имеет право на свободное использование своих способностей и имущества для предпринимательской и иной не запрещённой законом экономической деятельности.\n2) Производители товаров и услуг конкурируют между собой за спрос потребителей.\n3) В расчётах между предприятиями активно применяется безналичная форма.\n4) Цены на товары и услуги определяются соотношением спроса и предложения.\n5) Государство осуществляет централизованное распределение ресурсов.\n6) Предприятиям не приходится решать проблему ограниченности ресурсов.",
