          "number": 2,
          "type": "text",
          "prompt": "Выберите верные суждения и запишите цифры, под которыми они указаны.\n1) Бюджет называют профицитным, если доходы государства равны расходам.\n2) Государство перераспределяет через бюджет полученные доходы и направляет средства на обеспечение политики государства.\n3) Дефицит государственного бюджета может быть покрыт за счёт иностранных займов и кредитов. \n4) Для устранения дефицита своего бюджета государство снижает таможенные пошлины на ввозимые товары.\n5) Косвенные налоги выплачивают только отдельные юридические лица.\n6) Прямые налоги взимаются с доходов, собственности и определённых видов деятельности граждан и фирм.",
