          "prompt": "Выберите верные суждения о государственном бюджете.\n1) Государственный бюджет в Российской Федерации принимается Президентом Российской Федерации.\n2) Предоставление дотаций предприятиям — одна из статей доходов государственного бюджета.\n3) Государственный бюджет составляется с указанием источников поступления государственных доходов и направлений, каналов расходования средств.\n4) Профицит бюджета представляет собой ситуацию, когда доходы государства превышают расходы.\n5) Государственный бюджет — это финансовый план государства на определённый период времени.",
