          "id": "test-21-q-016",
          "number": 16,
          "type": "text",
          "prompt": "Выберите верные суждения о роли государства в экономике.\n1) Одной из экономических функций государства в рыночной экономике является компенсация внешних эффектов.\n2) В рыночной экономике государство выполняет функцию организации производства общественных благ.\n3) Политика государства, нацеленная на сокращение инфляции, преодоление спада экономики, ликвидацию безработицы, называется бюджетной.\n4) В случае спада экономической активности государство осуществляет стимулирующую политику.\n5) В экономике любого типа государство устанавливает цены на все товары и услуги.",
