          "type": "text",
          "prompt": "В ходе социологических опросов гражданам страны Z разных возрастных групп задавали вопрос: «Где вы предпочитаете хранить свои сбережения?». Полученные результаты (в % от числа опрошенных) представлены в виде диаграммы.\n\nНайдите в приведённом списке выводы, которые можно сделать на основе диаграммы, и запишите цифры, под которыми они указаны.\n1) Доля тех, кто предпочитает хранить сбережения в банке больше среди лиц старшей возрастной группы.\n2) Равные доли опрошенных младшей возрастной группы вкладывают сбережения в покупку ценных бумаг и предпочитают сохранять их в виде наличных денег.\n3) Доля тех, кто предпочитает вкладывать сбережения в покупку недвижимости среди старшей возрастной группы больше доли людей с таким же мнением среди младшей. \n4) Доля тех, кто предпочитает хранить сбережения в виде наличных денег среди опрошенных старшего поколения меньше доли людей с таким же мнением среди младшего.\n5) Равные доли опрошенных среди разных возрастных групп затруднились с ответом.",
