          "id": "test-24-q-022",
          "number": 22,
          "type": "text",
          "prompt": "Выберите верные суждения о ценных бумагах и запишите цифры, под которыми они указаны.\n\n 1) Ценными бумагами являются документы, соответствующие установленным законом требованиям и удостоверяющие обязательственные и иные права, осуществление или передача которых возможны только при предъявлении таких документов (документарные ценные бумаги).\n\n 2) Привилегированная акция, в отличие от обыкновенной акции, даёт право на участие в управлении фирмой и получение дивидендов.\n\n 3) Облигация – ценная бумага, удостоверяющая внесение её владельцем денежных средств и подтверждающая обязательство возместить ему номинальную стоимость этой ценной бумаги в предусмотренный срок с уплатой фиксированного процента, если иное не предусмотрено условиями выпуска.\n\n4) Вексель – документ, удостоверяющий факт внесения его владельцем определённой суммы в банк.\n\n 5) Документарные ценные бумаги могут быть предъявительскими (ценными бумагами на предъявителя), ордерными и именными.",
