          "type": "text",
          "prompt": "Выберите верные суждения об инфляции и антиинфляционной политике, Запишите цифры, под которыми они указаны.\n1) Высокий уровень инфляции способствует росту занятости и сокращению безработицы.\n2) Инфляция, как правило, приводит к увеличению расходов государственного бюджета, направляемых на реализацию социальных программ.\n3) Адаптационные меры (приспособление к инфляции) включают в себя индексацию доходов, контроль за уровнем цен и др.\n4) Гиперинфляция неуправляема и требует принятия со стороны государства чрезвычайных мер.\n5) Инфляция — процесс повышения общего уровня цен в стране, ведущий в итоге к снижению покупательной способности денег.",
