          "id": "test-25-q-003",
          "number": 3,
          "type": "text",
          "prompt": "Выберите верные суждения об инфляции и запишите цифры, под которыми они указаны.\n1) При инфляции издержек цены растут в результате увеличения затрат фирм на производство.\n2) Инфляция обесценивает накопленные фонды предприятий.\n3) Эмиссия денег является наиболее эффективным методом сдерживания инфляции.\n4) От гиперинфляции выигрывают группы населения, получающие фиксированные доходы. \n5) Инфляция — это превышение темпов роста денежной массы над темпами роста товарной массы.",
