          "id": "test-26-q-003",
          "number": 3,
          "type": "text",
          "prompt": "Выберите верные суждения о рынке труда и безработице. Запишите цифры, под которыми они указаны.\n1) К причинам фрикционной безработицы относят устаревание одних и появление других, ранее не существовавших профессий.\n2) Цена труда зависит только от количества и качества труда.\n3) На конкурентном рынке труда работники могут переходить от одного работодателя к другому безо всяких ограничений в установленном законодательством порядке.\n4) Спрос на рынке труда формируют работники.\n5) К государственным мерам борьбы с безработицей относят поощрение предпринимательской активности граждан.",
          "required": true,
