          "prompt": "Выберите верные суждения об экономическом росте и развитии и запишите цифры, под которыми они указаны.\n1) К факторам экстенсивного экономического роста относят использование достижений научно-технического прогресса.\n2) От экономического роста зависит богатство страны и благосостояние каждого гражданина.\n3) Экономический рост — это долгосрочная тенденция увеличения реального ВВП.\n4) Интенсивный экономический рост происходит на основе эффективного использования основных фондов.\n5) Рост объёмов потребления сырья, топлива является фактором интенсивного роста.",
