          "type": "text",
          "prompt": "Выберите верные суждения о политике и политической власти и запишите цифры, под которыми они указаны.\n1) Политикой называют совокупность отношений, складывающихся в системе производства, распределения, обмена и потребления материальных благ.\n2) Политическая власть — это право, способность и возможность отстаивать и претворять в жизнь определённые политические взгляды, установки и цели.\n3) К субъектам политики относятся политические партии и общественные движения.\n4) Субъектами политики являются избиратели.\n5) Любая власть в обществе носит политический характер.",
