          "prompt": "В конституции государства Z провозглашено, что государство Z — демократическая федеративная парламентская республика. Какие из приведённых признаков характеризуют форму правления Z? Запишите цифры, под которыми они указаны.\n1) двухпалатная структура парламента для обеспечения представительства субъектов\n2) наличие в парламенте нескольких партийных фракций \n3) действие конституций субъектов при верховенстве общей конституции \n4) правительство обеспечивает правопорядок и обороноспособность страны \n5) глава государства избирается парламентом \n6) правительство ответственно перед парламентом",
