          "type": "text",
          "prompt": "Установите соответствие между функциями и субъектами государственной власти Российской Федерации, которые их исполняют: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.\nСУБЪЕКТЫ ГОСУДАРСТВЕННОЙ ВЛАСТИ РФ\n\nA) назначение на пост Председателя Центрального банка РФ\nБ) осуществление мер по обеспечению законности, прав и свобод граждан\nB) объявление амнистии\nГ) обеспечение проведения в России единой финансовой, кредитной и денежной политики\nД) назначение выборов Президента РФ\n\nФУНКЦИИ\n1) Совет Федерации\n2) Государственная Дума \n3) Правительство РФ",
